package io.knowledgebrain.integration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.postgresql.ds.PGSimpleDataSource;import org.flywaydb.core.Flyway;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.server.ResponseStatusException;import io.knowledgebrain.contracts.integration.github.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_INTEGRATION_DATABASE_URL",matches=".+")
class GitHubStoreIntegrationTest {
 PGSimpleDataSource ds;JdbcTemplate sql;GitHubStore store;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space,actor;String trace="a".repeat(32),url="https://github.com/octocat/hello-world";GitHubClient.Repository source=new GitHubClient.Repository("1296269","octocat/Hello-World","https://github.com/octocat/Hello-World","main");
 @BeforeEach void setup(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_INTEGRATION_DATABASE_URL"));ds.setUser("brain_integration");ds.setPassword(System.getenv("BRAIN_TEST_INTEGRATION_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).load().migrate();sql=new JdbcTemplate(ds);store=new GitHubStore(ds,Clock.systemUTC());space=ids.next();actor=ids.next();}
 String key(){return UUID.randomUUID().toString().replace("-","");}
 GitHubStore.Repository connect(){return store.connect(space,actor,key(),url,source,trace).repository();}
 GitHubClient.Batch batch(){return new GitHubClient.Batch(source,List.of(new GitHubClient.Commit("a".repeat(40),"Subject <script>","octocat","2020-01-02T03:04:05Z"),new GitHubClient.Commit("b".repeat(40),"Second",null,"2020-01-03T03:04:05Z")),"a".repeat(40),false);}
 int events(){return sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid IN (SELECT repository_id FROM github_repository WHERE space_id=? UNION SELECT commit_id FROM github_commit WHERE space_id=?)",Integer.class,space,space);}
 void status(int value,org.junit.jupiter.api.function.Executable op){assertEquals(value,assertThrows(ResponseStatusException.class,op).getStatusCode().value());}
 @Test void connectedPrivateRepositoryRevisionAndEventCommitTogether()throws Exception{var v=connect();assertEquals(7,v.repositoryId().version());assertEquals("PRIVATE",v.visibility());assertEquals("ACTIVE",v.state());assertEquals(1,v.version());assertEquals(actor,v.connectedBy());assertNull(v.lastSyncedAt());assertEquals(1,events());var h=store.history(space,v.repositoryId(),Long.MAX_VALUE,10);assertEquals(v,h.getFirst().snapshot());assertEquals(7,h.getFirst().revisionId().version());var wire=sql.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.repositoryId());var e=GitHubEventEnvelopeV1.parseFrom(wire);assertEquals("integration-service",e.getProducer());assertEquals(space.toString(),e.getSpaceId());assertEquals(actor.toString(),e.getActorId());assertEquals(trace,e.getTraceId());assertEquals("GitHubRepositoryConnected",e.getEventType());assertEquals(7,UUID.fromString(e.getEventId()).version());assertEquals(v.externalId(),GitHubRepositorySnapshotV1.parseFrom(e.getPayload()).getExternalId());}
 @Test void creationReplaySurvivesSyncAndDisconnectWithoutReactivation(){String key=key();var v=store.connect(space,actor,key,url,source,trace).repository();status(409,()->store.replay(space,actor,key,"https://github.com/a/other"));store.sync(space,v.repositoryId(),actor,key(),1,batch(),trace);store.disconnect(space,v.repositoryId(),actor,2,trace);int count=events();var old=new GitHubStore(ds,Clock.systemUTC()).replay(space,actor,key,url);assertTrue(old.replay());assertEquals("RETIRED",old.repository().state());assertEquals(count,events());assertEquals(0,store.list(space,"ACTIVE",null,20).items().size());assertEquals(1,store.list(space,"RETIRED",null,20).items().size());assertEquals(2,store.commits(space,v.repositoryId(),null,20).items().size());assertNotEquals(v.repositoryId(),connect().repositoryId());}
 @Test void explicitSyncImportsOnlyNewImmutableCommitsAndRetainsIdempotentReceipt()throws Exception{var v=connect();String key=key();var first=store.sync(space,v.repositoryId(),actor,key,1,batch(),trace);assertEquals(2,first.sync().importedCount());assertEquals(2,first.sync().scannedCount());assertEquals(2,first.repository().version());assertEquals(4,events());var commits=store.commits(space,v.repositoryId(),null,100).items();assertEquals(2,commits.size());for(var c:commits){assertEquals(7,c.commitId().version());assertEquals("PUBLIC",c.sourceVisibility());assertEquals("PRIVATE",c.visibility());assertEquals(actor,c.importedBy());assertEquals(source.externalId(),c.repositoryExternalId());assertEquals(c,store.commit(space,v.repositoryId(),c.commitId()));var e=GitHubEventEnvelopeV1.parseFrom(sql.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,c.commitId()));assertEquals("GitHubCommitImported",e.getEventType());var p=GitHubCommitImportedV1.parseFrom(e.getPayload());assertEquals(c.sha(),p.getSha());assertEquals(c.committedAt(),p.getCommittedAt());assertEquals("PRIVATE",p.getVisibility());assertEquals("PUBLIC",p.getSourceVisibility());assertEquals(1,p.getVersion());}
  var second=store.sync(space,v.repositoryId(),actor,key(),2,batch(),trace);assertEquals(0,second.sync().importedCount());assertEquals(3,second.repository().version());assertEquals(commits,store.commits(space,v.repositoryId(),null,100).items());var replay=store.syncReplay(space,v.repositoryId(),actor,key,1);assertTrue(replay.replay());assertEquals(first.sync(),replay.sync());assertEquals(3,replay.repository().version());status(409,()->store.syncReplay(space,v.repositoryId(),actor,key,2));}
 @Test void sourceIdentityStaleVersionAndRetiredSyncNeverMutateFacts(){var v=connect();int before=events();var changed=new GitHubClient.Batch(new GitHubClient.Repository("42",source.fullName(),source.url(),"main"),batch().commits(),batch().headSha(),false);status(409,()->store.sync(space,v.repositoryId(),actor,key(),1,changed,trace));status(412,()->store.sync(space,v.repositoryId(),actor,key(),2,batch(),trace));assertEquals(before,events());assertEquals(0,store.commits(space,v.repositoryId(),null,20).items().size());store.disconnect(space,v.repositoryId(),actor,1,trace);before=events();status(409,()->store.sync(space,v.repositoryId(),actor,key(),2,batch(),trace));assertEquals(before,events());assertEquals(2,store.history(space,v.repositoryId(),Long.MAX_VALUE,10).size());}
 @Test void rollbackIncludesRepositoryReceiptCommitsAndOutbox(){var v=connect();status(400,()->store.sync(space,v.repositoryId(),actor,key(),1,batch(),"0".repeat(32)));assertEquals(1,store.get(space,v.repositoryId()).version());assertEquals(0,store.commits(space,v.repositoryId(),null,20).items().size());assertEquals(0,sql.queryForObject("SELECT count(*) FROM github_sync WHERE repository_id=?",Integer.class,v.repositoryId()));assertEquals(1,events());}
 @Test void spaceRepositoryCommitHistoryAndKeysetsStayIsolated(){var v=connect();store.sync(space,v.repositoryId(),actor,key(),1,batch(),trace);UUID foreign=ids.next();status(404,()->store.get(foreign,v.repositoryId()));status(404,()->store.commits(foreign,v.repositoryId(),null,20));status(404,()->store.history(foreign,v.repositoryId(),Long.MAX_VALUE,10));var first=store.commits(space,v.repositoryId(),null,1);assertNotNull(first.nextAfter());var second=store.commits(space,v.repositoryId(),first.nextAfter(),1);assertEquals(1,second.items().size());assertNull(second.nextAfter());assertNotEquals(first.items().getFirst().commitId(),second.items().getFirst().commitId());assertTrue(store.list(foreign,"ACTIVE",null,20).items().isEmpty());for(int limit:List.of(0,101))status(400,()->store.commits(space,v.repositoryId(),null,limit));}
 @Test void concurrentSameSyncHasOneReceiptAndOneImportPerSha()throws Exception{var v=connect();String key=key();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var start=new CyclicBarrier(3);var tasks=new ArrayList<Future<GitHubStore.Synced>>();for(int n=0;n<3;n++)tasks.add(pool.submit(()->{start.await();return store.sync(space,v.repositoryId(),actor,key,1,batch(),trace);}));var receipts=new HashSet<UUID>();int applied=0;for(var task:tasks){var a=task.get(20,TimeUnit.SECONDS);receipts.add(a.sync().syncId());if(!a.replay())applied++;}assertEquals(1,receipts.size());assertEquals(1,applied);assertEquals(4,events());assertEquals(2,store.get(space,v.repositoryId()).version());}}
 @Test void twoDifferentConcurrentSyncIntentsUseRepositoryCas()throws Exception{var v=connect();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var start=new CyclicBarrier(2);var tasks=new ArrayList<Future<Integer>>();for(int n=0;n<2;n++)tasks.add(pool.submit(()->{start.await();try{store.sync(space,v.repositoryId(),actor,key(),1,batch(),trace);return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));var results=new ArrayList<Integer>();for(var task:tasks)results.add(task.get(20,TimeUnit.SECONDS));results.sort(Integer::compareTo);assertEquals(List.of(200,412),results);assertEquals(4,events());}}
 @Test void duplicateActiveSourceRejectedWhileOtherPersonalSpaceIndependent(){connect();status(409,()->connect());UUID other=ids.next();assertEquals(other,store.connect(other,actor,key(),url,source,trace).repository().spaceId());assertEquals(1,store.list(space,"ACTIVE",null,100).items().size());}
 @Test void emptyObservedBatchDoesNotFabricateCommitOrCompletion(){var v=connect();var result=store.sync(space,v.repositoryId(),actor,key(),1,new GitHubClient.Batch(source,List.of(),null,false),trace);assertEquals(0,result.sync().scannedCount());assertEquals(0,result.sync().importedCount());assertNull(result.sync().headSha());assertEquals(2,events());}
}
